481		}
482		j := HookInputJSON{
483			HookType:   string(input.HookType),
484			SessionID:  input.SessionID,
485			SessionRef: input.SessionRef,
486			Timestamp:  input.Timestamp.Format(time.RFC3339),
487			UserPrompt: input.UserPrompt,
488			ToolName:   input.ToolName,
489			ToolUseID:  input.ToolUseID,
490			ToolInput:  input.ToolInput,
491			RawData:    input.RawData,
492		}
493		data, err := json.Marshal(j)
494		if err != nil {
495			return nil, fmt.Errorf("marshal hook input: %w", err)
496		}
497		return data, nil
498	}
499	
500	func marshalAgentSession(s *agent.AgentSession) ([]byte, error) {
501		j := AgentSessionJSON{
502			SessionID:     s.SessionID,
503			AgentName:     string(s.AgentName),
504			RepoPath:      s.RepoPath,
505			SessionRef:    s.SessionRef,
506			StartTime:     s.StartTime.Format(time.RFC3339),
507			NativeData:    s.NativeData,
508			ModifiedFiles: s.ModifiedFiles,
509			NewFiles:      s.NewFiles,
510			DeletedFiles:  s.DeletedFiles,
511		}
512		data, err := json.Marshal(j)
513		if err != nil {
514			return nil, fmt.Errorf("marshal agent session: %w", err)
515		}
516		return data, nil
517	}
518	
519	func unmarshalAgentSession(j *AgentSessionJSON) (*agent.AgentSession, error) {
520		var startTime time.Time
521		if j.StartTime != "" {
522			var err error
523			startTime, err = time.Parse(time.RFC3339, j.StartTime)
524			if err != nil {
525				return nil, fmt.Errorf("invalid start_time: %w", err)
526			}
527		}
528		return &agent.AgentSession{
529			SessionID:     j.SessionID,
530			AgentName:     types.AgentName(j.AgentName),
531			RepoPath:      j.RepoPath,
532			SessionRef:    j.SessionRef,
533			StartTime:     startTime,
534			NativeData:    j.NativeData,
535			ModifiedFiles: j.ModifiedFiles,
536			NewFiles:      j.NewFiles,
537			DeletedFiles:  j.DeletedFiles,
538		}, nil
539	}
540	
541	func convertTokenUsage(r *TokenUsageResponse) *agent.TokenUsage {
542		if r == nil {
543			return nil
544		}
545		usage := &agent.TokenUsage{
546			InputTokens:         r.InputTokens,
547			CacheCreationTokens: r.CacheCreationTokens,
548			CacheReadTokens:     r.CacheReadTokens,
549			OutputTokens:        r.OutputTokens,
550			APICallCount:        r.APICallCount,
551		}
552		if r.SubagentTokens != nil {
553			usage.SubagentTokens = convertTokenUsage(r.SubagentTokens)
554		}
555		return usage
556	}
