	}
	if kind == transcript.TypeAssistant {
		return transcript.TypeAssistant
	}
	return ""
}

// messageRole extracts the "role" field from a nested "message" object.
// Returns "" if the message field is absent or unparseable.
func messageRole(raw map[string]json.RawMessage) string {
	msgRaw, ok := raw["message"]
	if !ok {
		return ""
	}
	var msg struct {
		Role string `json:"role"`
	}
	if json.Unmarshal(msgRaw, &msg) == nil {
		return msg.Role
	}
	return ""
}

